import binascii
from boltons.mathutils import Bits

def test():
    print("Testing Bits('')")
    b = Bits('')
    print(f"b: {b!r}")
    print(f"as_bin: {b.as_bin()!r}")
    print(f"as_hex: {b.as_hex()!r}")
    try:
        print(f"as_bytes: {b.as_bytes()!r}")
    except Exception as e:
        print(f"as_bytes error: {e}")

    print("\nTesting Bits.from_hex('')")
    try:
        print(f"from_hex(''): {Bits.from_hex('')!r}")
    except Exception as e:
        print(f"from_hex error: {e}")

    print("\nTesting Bits.from_bytes(b'')")
    try:
        print(f"from_bytes(b''): {Bits.from_bytes(b'')!r}")
    except Exception as e:
        print(f"from_bytes error: {e}")

if __name__ == '__main__':
    test()

